CREATE TABLE settings_agent_sessions (
    session_id TEXT PRIMARY KEY NOT NULL CHECK(length(session_id)=36 AND session_id=lower(session_id) AND substr(session_id,9,1)='-' AND substr(session_id,14,1)='-' AND substr(session_id,19,1)='-' AND substr(session_id,24,1)='-' AND length(replace(session_id,'-',''))=32 AND replace(session_id,'-','') NOT GLOB '*[^0-9a-f]*' AND replace(session_id,'-','')!='00000000000000000000000000000000'),
    conversation_id TEXT NOT NULL UNIQUE CHECK(length(conversation_id)=36 AND conversation_id=lower(conversation_id) AND substr(conversation_id,9,1)='-' AND substr(conversation_id,14,1)='-' AND substr(conversation_id,19,1)='-' AND substr(conversation_id,24,1)='-' AND length(replace(conversation_id,'-',''))=32 AND replace(conversation_id,'-','') NOT GLOB '*[^0-9a-f]*' AND replace(conversation_id,'-','')!='00000000000000000000000000000000'),
    create_command_id TEXT NOT NULL UNIQUE CHECK(length(create_command_id)=36 AND create_command_id=lower(create_command_id) AND substr(create_command_id,9,1)='-' AND substr(create_command_id,14,1)='-' AND substr(create_command_id,19,1)='-' AND substr(create_command_id,24,1)='-' AND length(replace(create_command_id,'-',''))=32 AND replace(create_command_id,'-','') NOT GLOB '*[^0-9a-f]*' AND replace(create_command_id,'-','')!='00000000000000000000000000000000'),
    reservation TEXT NOT NULL CHECK(json_valid(reservation) AND json_type(reservation)='object' AND length(CAST(reservation AS BLOB))<=4096),
    CHECK(coalesce(json_remove(reservation,'$.version','$.session_id','$.host_id','$.principal_id','$.native_session_id','$.conversation_id','$.create_command_id','$.provider_binding_sha256','$.tools_sha256','$.created_at','$.expires_at')='{}' AND json_extract(reservation,'$.version')=1 AND json_extract(reservation,'$.session_id')=session_id AND json_extract(reservation,'$.conversation_id')=conversation_id AND json_extract(reservation,'$.create_command_id')=create_command_id AND length(json_extract(reservation,'$.host_id'))=36 AND json_extract(reservation,'$.host_id')=lower(json_extract(reservation,'$.host_id')) AND substr(json_extract(reservation,'$.host_id'),9,1)='-' AND substr(json_extract(reservation,'$.host_id'),14,1)='-' AND substr(json_extract(reservation,'$.host_id'),19,1)='-' AND substr(json_extract(reservation,'$.host_id'),24,1)='-' AND length(replace(json_extract(reservation,'$.host_id'),'-',''))=32 AND replace(json_extract(reservation,'$.host_id'),'-','') NOT GLOB '*[^0-9a-f]*' AND replace(json_extract(reservation,'$.host_id'),'-','')!='00000000000000000000000000000000' AND length(json_extract(reservation,'$.principal_id'))=36 AND json_extract(reservation,'$.principal_id')=lower(json_extract(reservation,'$.principal_id')) AND substr(json_extract(reservation,'$.principal_id'),9,1)='-' AND substr(json_extract(reservation,'$.principal_id'),14,1)='-' AND substr(json_extract(reservation,'$.principal_id'),19,1)='-' AND substr(json_extract(reservation,'$.principal_id'),24,1)='-' AND length(replace(json_extract(reservation,'$.principal_id'),'-',''))=32 AND replace(json_extract(reservation,'$.principal_id'),'-','') NOT GLOB '*[^0-9a-f]*' AND replace(json_extract(reservation,'$.principal_id'),'-','')!='00000000000000000000000000000000' AND length(json_extract(reservation,'$.native_session_id'))=36 AND json_extract(reservation,'$.native_session_id')=lower(json_extract(reservation,'$.native_session_id')) AND substr(json_extract(reservation,'$.native_session_id'),9,1)='-' AND substr(json_extract(reservation,'$.native_session_id'),14,1)='-' AND substr(json_extract(reservation,'$.native_session_id'),19,1)='-' AND substr(json_extract(reservation,'$.native_session_id'),24,1)='-' AND length(replace(json_extract(reservation,'$.native_session_id'),'-',''))=32 AND replace(json_extract(reservation,'$.native_session_id'),'-','') NOT GLOB '*[^0-9a-f]*' AND replace(json_extract(reservation,'$.native_session_id'),'-','')!='00000000000000000000000000000000' AND length(json_extract(reservation,'$.provider_binding_sha256'))=64 AND json_extract(reservation,'$.provider_binding_sha256') NOT GLOB '*[^0-9a-f]*' AND length(json_extract(reservation,'$.tools_sha256'))=64 AND json_extract(reservation,'$.tools_sha256') NOT GLOB '*[^0-9a-f]*' AND json_type(reservation,'$.created_at')='integer' AND json_extract(reservation,'$.created_at')>=0 AND json_type(reservation,'$.expires_at')='integer' AND json_extract(reservation,'$.expires_at')>=0 AND json_extract(reservation,'$.expires_at')>json_extract(reservation,'$.created_at'),0))
) STRICT;
CREATE TABLE settings_agent_turns (
    command_id TEXT PRIMARY KEY NOT NULL CHECK(length(command_id)=36 AND command_id=lower(command_id) AND substr(command_id,9,1)='-' AND substr(command_id,14,1)='-' AND substr(command_id,19,1)='-' AND substr(command_id,24,1)='-' AND length(replace(command_id,'-',''))=32 AND replace(command_id,'-','') NOT GLOB '*[^0-9a-f]*' AND replace(command_id,'-','')!='00000000000000000000000000000000'),
    session_id TEXT NOT NULL REFERENCES settings_agent_sessions(session_id),
    task_id TEXT NOT NULL UNIQUE CHECK(length(task_id)=36 AND task_id=lower(task_id) AND substr(task_id,9,1)='-' AND substr(task_id,14,1)='-' AND substr(task_id,19,1)='-' AND substr(task_id,24,1)='-' AND length(replace(task_id,'-',''))=32 AND replace(task_id,'-','') NOT GLOB '*[^0-9a-f]*' AND replace(task_id,'-','')!='00000000000000000000000000000000'),
    phase TEXT NOT NULL CHECK(phase IN ('armed','unknown','settled','stopped_uncertain')),
    record TEXT NOT NULL CHECK(json_valid(record) AND json_type(record)='object' AND length(CAST(record AS BLOB))<=4096),
    CHECK(coalesce(json_remove(record,'$.version','$.session_id','$.command_id','$.task_id','$.phase','$.attempt_id','$.model_attempts','$.tool_calls','$.charged_tokens','$.reserved_output_tokens','$.reported_input_tokens','$.reported_output_tokens','$.started_at','$.deadline','$.last_observed_wall','$.mutation_ids','$.provider_complete','$.usage_complete')='{}' AND json_extract(record,'$.version')=1 AND json_extract(record,'$.command_id')=command_id AND json_extract(record,'$.session_id')=session_id AND json_extract(record,'$.task_id')=task_id AND json_extract(record,'$.phase')=phase AND json_type(record,'$.model_attempts')='integer' AND json_extract(record,'$.model_attempts')>=0 AND json_extract(record,'$.model_attempts')<=4 AND json_type(record,'$.tool_calls')='integer' AND json_extract(record,'$.tool_calls')>=0 AND json_extract(record,'$.tool_calls')<=8 AND json_type(record,'$.charged_tokens')='integer' AND json_extract(record,'$.charged_tokens')>=0 AND json_type(record,'$.reserved_output_tokens')='integer' AND json_extract(record,'$.reserved_output_tokens')>=0 AND json_type(record,'$.reported_input_tokens')='integer' AND json_extract(record,'$.reported_input_tokens')>=0 AND json_type(record,'$.reported_output_tokens')='integer' AND json_extract(record,'$.reported_output_tokens')>=0 AND json_type(record,'$.started_at')='integer' AND json_extract(record,'$.started_at')>=0 AND json_type(record,'$.deadline')='integer' AND json_extract(record,'$.deadline')>=0 AND json_type(record,'$.last_observed_wall')='integer' AND json_extract(record,'$.last_observed_wall')>=0 AND json_extract(record,'$.deadline')>json_extract(record,'$.started_at') AND json_extract(record,'$.deadline')-json_extract(record,'$.started_at')<=120000 AND json_extract(record,'$.last_observed_wall')>=json_extract(record,'$.started_at') AND json_type(record,'$.mutation_ids')='array' AND json_array_length(record,'$.mutation_ids')<=8 AND json_type(record,'$.provider_complete') IN ('true','false') AND json_type(record,'$.usage_complete') IN ('true','false') AND ((json_extract(record,'$.model_attempts')=0 AND json_type(record,'$.attempt_id')='null' AND json_extract(record,'$.provider_complete')=0 AND json_extract(record,'$.usage_complete')=0) OR (json_extract(record,'$.model_attempts')>0 AND length(json_extract(record,'$.attempt_id'))=36 AND json_extract(record,'$.attempt_id')=lower(json_extract(record,'$.attempt_id')) AND substr(json_extract(record,'$.attempt_id'),9,1)='-' AND substr(json_extract(record,'$.attempt_id'),14,1)='-' AND substr(json_extract(record,'$.attempt_id'),19,1)='-' AND substr(json_extract(record,'$.attempt_id'),24,1)='-' AND length(replace(json_extract(record,'$.attempt_id'),'-',''))=32 AND replace(json_extract(record,'$.attempt_id'),'-','') NOT GLOB '*[^0-9a-f]*' AND replace(json_extract(record,'$.attempt_id'),'-','')!='00000000000000000000000000000000')) AND (json_extract(record,'$.tool_calls')>0 OR json_array_length(record,'$.mutation_ids')=0) AND (phase!='stopped_uncertain' OR (json_extract(record,'$.tool_calls')=0 AND json_array_length(record,'$.mutation_ids')=0 AND json_extract(record,'$.provider_complete')=0 AND json_extract(record,'$.usage_complete')=0)),0))
) STRICT;
CREATE INDEX settings_agent_turn_session ON settings_agent_turns(session_id,command_id);
CREATE TABLE settings_agent_cleanup (
    command_id TEXT PRIMARY KEY NOT NULL REFERENCES settings_agent_turns(command_id),
    attestation TEXT NOT NULL CHECK(json_valid(attestation) AND json_type(attestation)='object' AND length(CAST(attestation AS BLOB))<=512),
    CHECK(coalesce(json_remove(attestation,'$.version','$.command_id','$.exact_fence_sha256','$.owner_principal_id','$.attested_at','$.lost_ram_uncertainty_accepted')='{}' AND json_extract(attestation,'$.version')=1 AND json_extract(attestation,'$.command_id')=command_id AND length(json_extract(attestation,'$.exact_fence_sha256'))=64 AND json_extract(attestation,'$.exact_fence_sha256') NOT GLOB '*[^0-9a-f]*' AND length(json_extract(attestation,'$.owner_principal_id'))=36 AND json_extract(attestation,'$.owner_principal_id')=lower(json_extract(attestation,'$.owner_principal_id')) AND substr(json_extract(attestation,'$.owner_principal_id'),9,1)='-' AND substr(json_extract(attestation,'$.owner_principal_id'),14,1)='-' AND substr(json_extract(attestation,'$.owner_principal_id'),19,1)='-' AND substr(json_extract(attestation,'$.owner_principal_id'),24,1)='-' AND length(replace(json_extract(attestation,'$.owner_principal_id'),'-',''))=32 AND replace(json_extract(attestation,'$.owner_principal_id'),'-','') NOT GLOB '*[^0-9a-f]*' AND replace(json_extract(attestation,'$.owner_principal_id'),'-','')!='00000000000000000000000000000000' AND json_type(attestation,'$.attested_at')='integer' AND json_extract(attestation,'$.attested_at')>=0 AND json_type(attestation,'$.lost_ram_uncertainty_accepted')='true',0))
) STRICT;
CREATE INDEX settings_agent_reserved_conversation ON settings_agent_sessions(lower(replace(replace(replace(replace(conversation_id,'urn:uuid:',''),'-',''),'{',''),'}','')));
CREATE INDEX settings_agent_reserved_create_command ON settings_agent_sessions(lower(replace(replace(replace(replace(create_command_id,'urn:uuid:',''),'-',''),'{',''),'}','')));
CREATE INDEX settings_agent_reserved_command ON settings_agent_turns(lower(replace(replace(replace(replace(command_id,'urn:uuid:',''),'-',''),'{',''),'}','')));
CREATE INDEX settings_agent_reserved_task ON settings_agent_turns(lower(replace(replace(replace(replace(task_id,'urn:uuid:',''),'-',''),'{',''),'}','')));
CREATE VIEW settings_agent_reserved_ids AS
    SELECT lower(replace(replace(replace(replace(conversation_id,'urn:uuid:',''),'-',''),'{',''),'}','')) AS id FROM settings_agent_sessions
    UNION ALL SELECT lower(replace(replace(replace(replace(create_command_id,'urn:uuid:',''),'-',''),'{',''),'}','')) FROM settings_agent_sessions
    UNION ALL SELECT lower(replace(replace(replace(replace(command_id,'urn:uuid:',''),'-',''),'{',''),'}','')) FROM settings_agent_turns
    UNION ALL SELECT lower(replace(replace(replace(replace(task_id,'urn:uuid:',''),'-',''),'{',''),'}','')) FROM settings_agent_turns;

CREATE TABLE settings_agent_ordinary_ids (id TEXT PRIMARY KEY NOT NULL CHECK(length(id)=32 AND id NOT GLOB '*[^0-9a-f]*' AND id!='00000000000000000000000000000000')) STRICT, WITHOUT ROWID;

CREATE TRIGGER settings_agent_ordinary_no_update BEFORE UPDATE ON settings_agent_ordinary_ids BEGIN SELECT RAISE(ABORT,'ordinary identity exclusion is immutable'); END;
CREATE TRIGGER settings_agent_ordinary_no_delete BEFORE DELETE ON settings_agent_ordinary_ids BEGIN SELECT RAISE(ABORT,'ordinary identity exclusion is retained'); END;

INSERT OR IGNORE INTO settings_agent_ordinary_ids(id) SELECT lower(replace(replace(replace(replace(candidate.value,'urn:uuid:',''),'-',''),'{',''),'}','')) AS id FROM (SELECT v.value AS value FROM conversations AS t,json_each(json_array(t.id)) AS v) AS candidate WHERE typeof(candidate.value)='text' AND length(lower(replace(replace(replace(replace(candidate.value,'urn:uuid:',''),'-',''),'{',''),'}','')))=32 AND lower(replace(replace(replace(replace(candidate.value,'urn:uuid:',''),'-',''),'{',''),'}','')) NOT GLOB '*[^0-9a-f]*' AND lower(replace(replace(replace(replace(candidate.value,'urn:uuid:',''),'-',''),'{',''),'}',''))!='00000000000000000000000000000000';

CREATE TRIGGER settings_agent_exclude_conversations_insert BEFORE INSERT ON conversations
WHEN EXISTS(SELECT 1 FROM settings_agent_sessions) AND EXISTS(SELECT 1 FROM (SELECT lower(replace(replace(replace(replace(candidate.value,'urn:uuid:',''),'-',''),'{',''),'}','')) AS id FROM (SELECT v.value AS value FROM json_each(json_array(NEW.id)) AS v) AS candidate WHERE typeof(candidate.value)='text' AND length(lower(replace(replace(replace(replace(candidate.value,'urn:uuid:',''),'-',''),'{',''),'}','')))=32 AND lower(replace(replace(replace(replace(candidate.value,'urn:uuid:',''),'-',''),'{',''),'}','')) NOT GLOB '*[^0-9a-f]*' AND lower(replace(replace(replace(replace(candidate.value,'urn:uuid:',''),'-',''),'{',''),'}',''))!='00000000000000000000000000000000') AS candidate JOIN settings_agent_reserved_ids AS r ON r.id=candidate.id)
BEGIN SELECT RAISE(ABORT,'ordinary identity overlaps restricted Settings namespace'); END;

CREATE TRIGGER settings_agent_index_conversations_insert AFTER INSERT ON conversations
BEGIN INSERT OR IGNORE INTO settings_agent_ordinary_ids(id) SELECT lower(replace(replace(replace(replace(candidate.value,'urn:uuid:',''),'-',''),'{',''),'}','')) AS id FROM (SELECT v.value AS value FROM json_each(json_array(NEW.id)) AS v) AS candidate WHERE typeof(candidate.value)='text' AND length(lower(replace(replace(replace(replace(candidate.value,'urn:uuid:',''),'-',''),'{',''),'}','')))=32 AND lower(replace(replace(replace(replace(candidate.value,'urn:uuid:',''),'-',''),'{',''),'}','')) NOT GLOB '*[^0-9a-f]*' AND lower(replace(replace(replace(replace(candidate.value,'urn:uuid:',''),'-',''),'{',''),'}',''))!='00000000000000000000000000000000'; END;

