CREATE TRIGGER settings_agent_index_conversations_update AFTER UPDATE OF id ON conversations
BEGIN INSERT OR IGNORE INTO settings_agent_ordinary_ids(id) SELECT lower(replace(replace(replace(replace(candidate.value,'urn:uuid:',''),'-',''),'{',''),'}','')) AS id FROM (SELECT v.value AS value FROM json_each(json_array(NEW.id)) AS v) AS candidate WHERE typeof(candidate.value)='text' AND length(lower(replace(replace(replace(replace(candidate.value,'urn:uuid:',''),'-',''),'{',''),'}','')))=32 AND lower(replace(replace(replace(replace(candidate.value,'urn:uuid:',''),'-',''),'{',''),'}','')) NOT GLOB '*[^0-9a-f]*' AND lower(replace(replace(replace(replace(candidate.value,'urn:uuid:',''),'-',''),'{',''),'}',''))!='00000000000000000000000000000000'; END;

INSERT OR IGNORE INTO settings_agent_ordinary_ids(id) SELECT lower(replace(replace(replace(replace(candidate.value,'urn:uuid:',''),'-',''),'{',''),'}','')) AS id FROM (SELECT v.value AS value FROM events AS t,json_each(json_array(t.id,t.conversation_id)) AS v UNION ALL SELECT json_extract(CASE WHEN json_extract(CASE WHEN json_valid(CAST(t.payload AS TEXT)) THEN CAST(t.payload AS TEXT) ELSE '{}' END,'$.schema_version')=1 THEN CASE WHEN json_valid(CAST(t.payload AS TEXT)) THEN CAST(t.payload AS TEXT) ELSE '{}' END ELSE '{}' END,p.value) AS value FROM events AS t,json_each('["$.conversation_id","$.causation_id","$.payload.task_id","$.payload.command_id","$.payload.wait_id","$.payload.child_task_id","$.payload.task.id","$.payload.task.conversation_id","$.payload.task.parent_task_id","$.payload.task.originating_command_id","$.payload.report.task_id","$.payload.report.command_id","$.payload.notification.task_id","$.payload.notification.execution_conversation_id"]') AS p UNION ALL SELECT a.value AS value FROM events AS t,json_each(CASE WHEN json_extract(CASE WHEN json_valid(CAST(t.payload AS TEXT)) THEN CAST(t.payload AS TEXT) ELSE '{}' END,'$.schema_version')=1 THEN CASE WHEN json_valid(CAST(t.payload AS TEXT)) THEN CAST(t.payload AS TEXT) ELSE '{}' END ELSE '{}' END,'$.payload.children') AS a WHERE a.type='text') AS candidate WHERE typeof(candidate.value)='text' AND length(lower(replace(replace(replace(replace(candidate.value,'urn:uuid:',''),'-',''),'{',''),'}','')))=32 AND lower(replace(replace(replace(replace(candidate.value,'urn:uuid:',''),'-',''),'{',''),'}','')) NOT GLOB '*[^0-9a-f]*' AND lower(replace(replace(replace(replace(candidate.value,'urn:uuid:',''),'-',''),'{',''),'}',''))!='00000000000000000000000000000000';

