INSERT OR IGNORE INTO settings_agent_ordinary_ids(id) SELECT lower(replace(replace(replace(replace(candidate.value,'urn:uuid:',''),'-',''),'{',''),'}','')) AS id FROM (SELECT v.value AS value FROM transport_inbox AS t,json_each(json_array(t.command_id)) AS v UNION ALL SELECT json_extract(CASE WHEN json_extract(CASE WHEN json_valid(CAST(t.payload AS TEXT)) THEN CAST(t.payload AS TEXT) ELSE '{}' END,'$.schema_version')=1 THEN CASE WHEN json_valid(CAST(t.payload AS TEXT)) THEN CAST(t.payload AS TEXT) ELSE '{}' END ELSE '{}' END,p.value) AS value FROM transport_inbox AS t,json_each('["$.payload.command.command_id","$.payload.command.conversation_id","$.payload.command.payload.task_id","$.payload.command.payload.parent_task_id","$.payload.command_id","$.payload.batch.cursor.conversation_id","$.payload.cursor.conversation_id"]') AS p UNION ALL SELECT json_extract(CASE WHEN a.type='object' THEN a.value ELSE '{}' END,p.value) AS value FROM transport_inbox AS t,json_each(CASE WHEN json_extract(CASE WHEN json_valid(CAST(t.payload AS TEXT)) THEN CAST(t.payload AS TEXT) ELSE '{}' END,'$.schema_version')=1 THEN CASE WHEN json_valid(CAST(t.payload AS TEXT)) THEN CAST(t.payload AS TEXT) ELSE '{}' END ELSE '{}' END,'$.payload.request.cursors') AS a,json_each('["$.conversation_id"]') AS p UNION ALL SELECT json_extract(CASE WHEN a.type='object' THEN a.value ELSE '{}' END,p.value) AS value FROM transport_inbox AS t,json_each(CASE WHEN json_extract(CASE WHEN json_valid(CAST(t.payload AS TEXT)) THEN CAST(t.payload AS TEXT) ELSE '{}' END,'$.schema_version')=1 THEN CASE WHEN json_valid(CAST(t.payload AS TEXT)) THEN CAST(t.payload AS TEXT) ELSE '{}' END ELSE '{}' END,'$.payload.batch.events') AS a,json_each('["$.conversation_id","$.causation_id","$.payload.task_id","$.payload.command_id","$.payload.wait_id","$.payload.child_task_id","$.payload.task.id","$.payload.task.conversation_id","$.payload.task.parent_task_id","$.payload.task.originating_command_id","$.payload.report.task_id","$.payload.report.command_id","$.payload.notification.task_id","$.payload.notification.execution_conversation_id"]') AS p UNION ALL SELECT b.value AS value FROM transport_inbox AS t,json_each(CASE WHEN json_extract(CASE WHEN json_valid(CAST(t.payload AS TEXT)) THEN CAST(t.payload AS TEXT) ELSE '{}' END,'$.schema_version')=1 THEN CASE WHEN json_valid(CAST(t.payload AS TEXT)) THEN CAST(t.payload AS TEXT) ELSE '{}' END ELSE '{}' END,'$.payload.batch.events') AS a,json_each(CASE WHEN a.type='object' THEN a.value ELSE '{}' END,'$.payload.children') AS b WHERE b.type='text') AS candidate WHERE typeof(candidate.value)='text' AND length(lower(replace(replace(replace(replace(candidate.value,'urn:uuid:',''),'-',''),'{',''),'}','')))=32 AND lower(replace(replace(replace(replace(candidate.value,'urn:uuid:',''),'-',''),'{',''),'}','')) NOT GLOB '*[^0-9a-f]*' AND lower(replace(replace(replace(replace(candidate.value,'urn:uuid:',''),'-',''),'{',''),'}',''))!='00000000000000000000000000000000';

